-- =====================================================================
-- Atwater seed · 0004 · NASEM DRIs, all life-stage groups
--
-- GENERATED by importers/dri from catalog/data/nasem-dri/*.csv.
-- Do not edit by hand: change the CSVs or mapping.go and regenerate.
-- Applied seed files are checksum-tracked, so a regenerated file needs
-- a new seed number rather than replacing this one once applied.
--
-- Source: NASEM 2019, Dietary Reference Intakes for Sodium and
-- Potassium, Appendix J (consolidated DRI summary tables); see
-- catalog/data/nasem-dri/SOURCES.md.
--
-- 942 reference values for 22 life-stage groups. Rows the 0001/0002 seeds
-- already hold must match exactly, or this file raises and rolls back.
--
-- Columns not loaded:
--   amdr.csv: n-3 polyunsaturated fatty acids (α-linolenic acid) (% of energy): not a catalog nutrient yet
--   amdr.csv: n-6 polyunsaturated fatty acids (linoleic acid) (% of energy): not a catalog nutrient yet
--   cdrr_sodium.csv: printed_as: text as printed, kept for review
--   cdrr_sodium.csv: source_table: provenance, kept for review
--   rda_ai_elements.csv: Chloride (g/d): not a catalog nutrient yet
--   rda_ai_elements.csv: Chromium (μg/d): not a catalog nutrient yet
--   rda_ai_elements.csv: Fluoride (mg/d): not a catalog nutrient yet
--   rda_ai_elements.csv: Iodine (μg/d): not a catalog nutrient yet
--   rda_ai_elements.csv: Molybdenum (μg/d): not a catalog nutrient yet
--   rda_ai_macronutrients.csv: Linoleic Acid (g/d): not a catalog nutrient yet
--   rda_ai_macronutrients.csv: Total Water (L/d): total water includes beverages and drinking water; the catalog's water nutrient is water in food. Belongs with hydration targets.
--   rda_ai_macronutrients.csv: α-Linolenic Acid (g/d): not a catalog nutrient yet
--   rda_ai_vitamins.csv: Biotin (μg/d): not a catalog nutrient yet
--   ul_elements.csv: Arsenic: no UL established (all ND)
--   ul_elements.csv: Boron (mg/d): not a catalog nutrient yet
--   ul_elements.csv: Chloride (g/d): not a catalog nutrient yet
--   ul_elements.csv: Chromium: no UL established (all ND)
--   ul_elements.csv: Fluoride (mg/d): not a catalog nutrient yet
--   ul_elements.csv: Iodine (μg/d): not a catalog nutrient yet
--   ul_elements.csv: Molybdenum (μg/d): not a catalog nutrient yet
--   ul_elements.csv: Nickel (mg/d): not a catalog nutrient yet
--   ul_elements.csv: Potassium: no UL established (all ND)
--   ul_elements.csv: Silicon: no UL established (all ND)
--   ul_elements.csv: Sodium: no UL established (all ND)
--   ul_elements.csv: Sulfate: no UL established (all ND)
--   ul_elements.csv: Vanadium (mg/d): not a catalog nutrient yet
--   ul_vitamins.csv: Biotin: no UL established (all ND)
--   ul_vitamins.csv: Carotenoids: no UL established (all ND)
--   ul_vitamins.csv: Folate (μg/d): UL is synthetic folic acid in μg, not DFE; needs the folic acid nutrient (FDC 431).
--   ul_vitamins.csv: Pantothenic Acid: no UL established (all ND)
--   ul_vitamins.csv: Riboflavin: no UL established (all ND)
--   ul_vitamins.csv: Thiamin: no UL established (all ND)
--   ul_vitamins.csv: Vitamin A (μg/d): UL applies to preformed vitamin A only; the catalog nutrient is RAE, which includes carotenoids. Needs a retinol nutrient.
--   ul_vitamins.csv: Vitamin B12: no UL established (all ND)
--   ul_vitamins.csv: Vitamin K: no UL established (all ND)
-- =====================================================================
BEGIN;

CREATE TEMP TABLE dri_stage (life_stage_code text, sex text, age_min_months int, age_max_months int,
                              physiological_state text, label text) ON COMMIT DROP;

DO $$
DECLARE bad text;
BEGIN
  SELECT string_agg(g.life_stage_code, ', ') INTO bad
    FROM dri_stage s JOIN ref.life_stage_group g USING (life_stage_code)
   WHERE (g.authority_code, g.sex, g.age_min_months, g.age_max_months, g.physiological_state)
         IS DISTINCT FROM ('NASEM_DRI', s.sex, s.age_min_months, s.age_max_months, s.physiological_state);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'existing life-stage groups differ from the generated ones: %', bad;
  END IF;
END $$;

SELECT s.life_stage_code, 'NASEM_DRI', s.sex, s.age_min_months, s.age_max_months, s.physiological_state, s.label
  FROM dri_stage s
 WHERE NOT EXISTS (SELECT 1 FROM ref.life_stage_group g WHERE g.life_stage_code = s.life_stage_code)
 ORDER BY s.life_stage_code;

CREATE TEMP TABLE dri_value (life_stage_code text, nutrient_code text, value_type text, basis text,
                              amount_low numeric, amount_high numeric, unit_code text, applies_to text,
                              note text, source_url text) ON COMMIT DROP;

DO $$
DECLARE bad text;
BEGIN
  SELECT string_agg(DISTINCT v.nutrient_code, ', ') INTO bad
    FROM dri_value v LEFT JOIN ref.nutrient n ON n.code = v.nutrient_code WHERE n.nutrient_id IS NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'unknown nutrient codes: %', bad; END IF;

  SELECT string_agg(DISTINCT v.nutrient_code || ' (' || v.unit_code || ' vs ' || n.unit_code || ')', ', ') INTO bad
    FROM dri_value v JOIN ref.nutrient n ON n.code = v.nutrient_code
   WHERE v.unit_code <> CASE WHEN v.basis = 'pct_energy' THEN '%' ELSE n.unit_code END;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'units differ from the nutrients'' canonical units: %', bad; END IF;

  SELECT string_agg(r.life_stage_code || ' ' || v.nutrient_code || ' ' || r.value_type || ' ' || r.basis
                    || ': catalog ' || coalesce(r.amount_low::text, '-') || '/' || coalesce(r.amount_high::text, '-')
                    || ' ' || r.unit_code || ' ' || r.applies_to
                    || ', generated ' || coalesce(v.amount_low::text, '-') || '/' || coalesce(v.amount_high::text, '-')
                    || ' ' || v.unit_code || ' ' || v.applies_to, '; ') INTO bad
    FROM dri_value v
    JOIN ref.nutrient n ON n.code = v.nutrient_code
    JOIN ref.nutrient_reference_value r
      ON (r.authority_code, r.edition, r.life_stage_code, r.nutrient_id, r.value_type, r.basis)
       = ('NASEM_DRI', 'consolidated-2019', v.life_stage_code, n.nutrient_id, v.value_type, v.basis)
   WHERE (r.amount_low, r.amount_high, r.unit_code, r.applies_to)
         IS DISTINCT FROM (v.amount_low, v.amount_high, v.unit_code, v.applies_to);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'existing reference values differ from the transcription: %', bad; END IF;
END $$;

   amount_low, amount_high, unit_code, applies_to, note, source_url)
SELECT 'NASEM_DRI', 'consolidated-2019', v.life_stage_code, n.nutrient_id, v.value_type, v.basis,
       v.amount_low, v.amount_high, v.unit_code, v.applies_to, v.note, v.source_url
  FROM dri_value v JOIN ref.nutrient n ON n.code = v.nutrient_code
 WHERE NOT EXISTS (
   SELECT 1 FROM ref.nutrient_reference_value r
    WHERE (r.authority_code, r.edition, r.life_stage_code, r.nutrient_id, r.value_type, r.basis)
        = ('NASEM_DRI', 'consolidated-2019', v.life_stage_code, n.nutrient_id, v.value_type, v.basis))
 ORDER BY v.life_stage_code, v.nutrient_code, v.value_type, v.basis;

COMMIT;
